import json,pathlib,statistics
p=pathlib.Path(__file__).resolve().parent;d=json.loads((p/'results.json').read_text())
lines=['# Matched retirement traversal evidence','','Measured source `c51bfc5`, runtime `d68b1f5`. Three same-source best-SSE2-pipeline variants differ only in retirement traversal: header walk, always start-map, or adaptive previous-cycle mean stride <=48 bytes. Contemporaneous V8 provides an end-to-end gate, not isolated collector efficiency. Explicit Eden 2 MiB, two 8 MiB old semispaces. All 24 audits and 72 timing processes passed. Audits use 128 warmup calls; timed processes use 100 warmups and nine batches of 32 calls, three rotating rounds.','','| Case | Variant | Median ms | Process medians ms | Ratio to V8 | Timed minor/full | Peak RSS MiB | Go heap MiB |','|---|---|---:|---|---:|---|---:|---:|']
for c in dict.fromkeys(r['case'] for r in d['rows']):
 groups={v:[r['result'] for r in d['rows'] if r['case']==c and r['variant']==v] for v in ['headers','startmap','adaptive','v8']}
 v8=statistics.median(statistics.median(r['samples_ns']) for r in groups['v8'])
 for v,rs in groups.items():
  ts=[statistics.median(r['samples_ns'])/1e6 for r in rs];m=statistics.median(ts)
  gc='unobserved' if v=='v8' else ', '.join(sorted(set(str(r['after']['MinorCollections']-r['before']['MinorCollections'])+'/'+str(r['after']['FullCollections']-r['before']['FullCollections']) for r in rs)))
  rss=statistics.median((r['memory']['VmHWM_kib'] if v=='v8' else r['proc_VmHWM_kib'])/1024 for r in rs)
  heap='n/a' if v=='v8' else f'{statistics.median(r["go_after"]["HeapAlloc"] for r in rs)/1048576:.2f}'
  lines.append(f'| {c} | {v} | {m:.4f} | '+', '.join(f'{t:.4f}' for t in ts)+f' | {m*1e6/v8:.3f}x | {gc} | {rss:.2f} | {heap} |')
lines+=['','## Interpretation','','Struct improves consistently: always-map is 13.9% lower and adaptive is 11.7% lower in median than headers, with every map/adaptive sample below every header sample. Other cases overlap or have mixed paired-round directions; no general speedup is established there. This supports the struct retirement opportunity without proving always-map is appropriate for all object densities or phase changes. Previous-cycle adaptation can lag workload transitions. The independent crossover microbenchmarks remain relevant to policy selection.','','Every workload still misses the <=1.15x V8 gate for all three variants. Exact artifact hashes, checksums and object-allocation counts passed; collection counts are retained above. No aggregate substitutes for misses. V8 uses --no-liftoff (Node24.22.1/V8 13.6.233.17-node.58); its internal allocation/elision and collection behavior are unobserved. Resident memory and Go heap are not equalized engine budgets. Direct copied/promoted and scan counters remain uninstrumented. Compilation is excluded; host Go GC runs outside timing after warmup. Worker builds/tests were excluded from this window, but host scheduling/frequency remain uncontrolled.','']
(p/'summary.md').write_text('\n'.join(lines))
